// 予兆：隠れた値を、情報源ごとの偏りを通して少しずつ知らせる。状態は変えない。
// 大蔵省は楽観的、頭取は隠す、新聞は正確だが遅い、仁科は忠誠が高ければ正確、鬼塚は金の流れに敏感。
(function (root) {
  'use strict';

  const TONES = ['calm', 'calm', 'warn', 'bad'];
  const noise = (rnd, w) => (rnd() * 2 - 1) * w;
  // 見立ての値を段階に分け、その段階の文から1つ選ぶ（使い終えた文は出さない）
  function pick(s, rnd, val, cuts, lines) {
    let k = 0; while (k < cuts.length && val >= cuts[k]) k++;
    const pool = lines[k].filter(x => !s.news.some(n => n.msg === x));
    if (!pool.length) return null;
    return { text: pool[Math.floor(rnd() * pool.length)], tone: TONES[Math.min(k, 3)] };
  }

  const omens = [
    {
      src: '大蔵省', // 楽観的に言う
      say: (s, rnd) => pick(s, rnd, s.v.damage - 14 + noise(rnd, 4), [28, 40, 52], [
        ['銀行局の課長：「金融機関の体力は十分です。地価の調整は一時的なものと見ています」', '銀行局の課長：「引当金は手当て済みです。ご心配には及びません」'],
        ['銀行局の課長：「一部の地銀で引当が増えていますが、想定の範囲内です」', '銀行局の課長：「不動産向けの融資は、担保で十分に保全されています」'],
        ['銀行局の課長：「数字を精査中です。今の段階で騒ぐのは得策ではありません」', '銀行局の課長：「業界には自主的な処理を促しています。表に出せば取り付けが起きます」'],
        ['銀行局の課長が、珍しく目を伏せる。「担保の評価額が、もう帳簿と合いません」']
      ])
    },
    {
      src: '頭取', when: (s) => !s.flags.liquidate, // 隠す。追い貸しを認めていると、さらに隠す
      say: (s, rnd) => pick(s, rnd, s.v.damage - (s.flags.forbear ? 18 : 6) + noise(rnd, 5), [30, 42, 54], [
        ['北陽銀行の頭取：「おかげさまで、取引先も持ち直しつつあります」', '北陽銀行の頭取が後援会のゴルフに顔を出す。上機嫌だ'],
        ['北陽銀行の頭取：「一部の取引先が、少し返済を待ってほしいと言っておりまして」'],
        ['北陽銀行の頭取：「来期の決算は……何とかします。何とか」', '北陽銀行の頭取が、後援会の会合を欠席した'],
        ['北陽銀行の頭取：「先生、正直に申し上げます。もう追い貸しでしか回っておりません」']
      ])
    },
    {
      src: '新聞', // 正確だが遅い（世論の危機認識に連動）
      say: (s, rnd) => pick(s, rnd, s.v.aware, [15, 30, 50], [
        ['経済面の片隅に「都心の地価、下落の兆し」', '「財テク企業の含み損」を報じる小さな記事'],
        ['経済面のトップに「銀行の不良債権、数兆円規模か」', '「住専の融資残高が膨張」と報じる記事'],
        ['社説が「不良債権の処理を急げ」と書く', '見出しに「貸し渋り」という言葉が出始めた'],
        ['一面に「金融危機」の四文字', '夕刊の一面に「信用不安、地銀に広がる」']
      ])
    },
    {
      src: '仁科', when: (s) => s.v.nishina >= 50 && !s.flags.nishinaGone, // 忠誠が高いほど正確
      say: (s, rnd) => {
        if (s.v.chain >= 8 && rnd() < 0.5) return pick(s, rnd, s.v.chain, [8, 20, 35], [[],
          ['仁科：「地元の工務店が二軒、手形を落とせませんでした」'],
          ['仁科：「北陽の取引先が、今月だけで五社倒れました。商店街のシャッターが目立ちます」'],
          ['仁科：「先生、地元はもう、火の手が止まりません」']]);
        return pick(s, rnd, s.v.damage + noise(rnd, (100 - s.v.nishina) / 6), [32, 42, 52], [
          ['仁科：「地元の不動産屋の羽振りが、少し落ちております」'],
          ['仁科：「北陽の貸出先で、三つほど怪しいところがございます」', '仁科：「北陽の支店長の顔色が、春から優れません」'],
          ['仁科：「北陽の支店長が、夜中に後援会長の家を回っております。金策です」'],
          ['仁科：「先生、お父上の手帳にあった数字を、もう超えております」']
        ]);
      }
    },
    {
      src: '鬼塚', // 金の流れに敏感
      say: (s, rnd) => {
        if (s.v.funding < 85 && rnd() < 0.5) return pick(s, rnd, 100 - s.v.funding, [15, 25, 40], [[],
          ['鬼塚：「パーティ券の戻りが鈍いです。先月より二割減です」'],
          ['鬼塚：「献金の約束が、三件取り消されました」'],
          ['鬼塚：「先生、金庫がもう、底が見えてます」']]);
        if (s.don.status !== 'active') return null;
        return pick(s, rnd, s.v.donScandal + noise(rnd, 6), [45, 55, 70], [
          ['鬼塚：「派閥の金の流れは、特に変わりありません」'],
          ['鬼塚：「運送会社の経理部長が、検察に呼ばれたらしいです」', '鬼塚：「権藤事務所の帳簿係が、急に休みを取りました」'],
          ['鬼塚：「派閥の事務所から、段ボールを運び出す業者が来てました」'],
          ['鬼塚：「権藤事務所の金庫番が、もう全部しゃべってるって噂です」']
        ]);
      }
    },
    {
      src: '週刊誌', // 噂を大きく書く。外れることもある
      say: (s, rnd) => {
        if (s.v.scandal >= 25 && rnd() < 0.5) return pick(s, rnd, s.v.scandal, [25, 35, 50], [[],
          ['記者が、地元の後援会の周りを嗅ぎ回っているらしい'],
          ['週刊誌の記者から事務所に電話。「お父上の裏の帳面について、お話を」'],
          ['週刊誌の次号の見出しに、あなたの名前が入っていると聞いた']]);
        if (s.don.status !== 'active') return null;
        return pick(s, rnd, s.v.donScandal - 6 + noise(rnd, 10), [45, 55, 70], [
          ['週刊誌が「永田町の金庫番」の特集を組む。父の名前が小さく出ている'],
          ['週刊誌が「運送会社から政界へ流れた金」を書く。名前は伏せてある'],
          ['週刊誌の見出し：「権藤嘉平、5億円の行方」'],
          ['週刊誌の見出し：「権藤逮捕へ、秒読み」']
        ]);
      }
    },
    {
      src: '財界', when: (s) => s.v.damage >= 38 || s.v.chain >= 5,
      say: (s, rnd) => pick(s, rnd, s.v.chain * 2 + s.v.damage * 0.5, [30, 45, 60], [
        ['経済団体の会合で、不動産会社の役員が「地価はまた戻る」と笑う'],
        ['ゼネコンの役員がこぼす。「年を越せない下請けが出るかもしれない」'],
        ['経済団体の会合で、銀行の役員の席が空いている'],
        ['財界の重鎮：「政治は何をしている。もう銀行同士では支えきれん」']
      ])
    },
    {
      src: '街の声', when: (s) => s.v.backlash >= 15 || s.v.aware >= 40,
      say: (s, rnd) => s.v.backlash >= 15
        ? pick(s, rnd, s.v.backlash, [15, 30, 45], [[],
          ['タクシーの運転手：「銀行ばっかり助けて、うちらは知らん顔か」'],
          ['駅前で「税金を返せ」のビラが配られている'],
          ['地元の集会で、救済の話を出すと野次が飛ぶ']])
        : pick(s, rnd, s.v.aware, [40, 55, 70], [[],
          ['商店街の会長：「お客さんの財布が、急に固くなった」'],
          ['後援会の婦人部：「息子の会社がボーナスを出さないって」'],
          ['地元の信用金庫の前に、朝から人が並んでいる']])
    },
    {
      src: '物価', when: (s) => s.ind.cpi >= 3, // 物価の圧力（型1の予兆）
      say: (s, rnd) => pick(s, rnd, s.ind.cpi, [3, 4, 5], [[],
        ['主婦：「スーパーの卵が、また10円上がった」', '新聞：「物価上昇率、3%台に」'],
        ['主婦：「スーパーの値札が毎月変わる」', '日銀の理事：「物価の動きを注視しています」'],
        ['新聞：「狂乱物価の再来か」', '労働組合：「賃上げが物価に追いつかない。春闘で闘う」']
      ])
    },
    {
      src: '河川局', when: (s) => s.t >= 6, // 防災力（型2の予兆）。災害が来るかは教えない。備えの状態だけを知らせる
      say: (s, rnd) => pick(s, rnd, 100 - s.v.bousai, [35, 50, 60], [
        ['河川局：「地下放水路の掘削が順調です。完成すれば、荒川の水を江戸川に逃がせます」'],
        ['河川局：「堤防の補強は、計画の6割で止まっています」'],
        ['河川局：「予算が削られ、堤防の工事が止まりました。去年の大雨では、あと50センチで溢れるところでした」'],
        ['河川局長：「先生、正直に申し上げます。大きな台風が来たら、下町は守れません」']
      ])
    }
  ];

  const api = { omens };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.REB_OMENS = api;
})(typeof window !== 'undefined' ? window : globalThis);
